<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{storeToRefs}from'pinia';import InventorySubnav from '../components/InventorySubnav.vue';import InventoryScenarioBar from '../components/InventoryScenarioBar.vue';import{useInventoryStore}from'../runtime/inventory-store';import'./inventory-views.css';const props=defineProps<{batchOnly?:boolean}>();const store=useInventoryStore();const{workspace,loading,error,scenario,actor}=storeToRefs(store);const keyword=ref('');const direction=ref('');const rows=computed(()=>workspace.value.movements.filter(x=>!props.batchOnly||x.productionDate!==null).filter(x=>!direction.value||x.direction===direction.value).filter(x=>!keyword.value||[x.sourceId,x.sourceType,x.sku?.skuCode,x.sku?.productName,x.batchNumber].some(v=>v?.toLocaleLowerCase().includes(keyword.value.toLocaleLowerCase()))));const q=(n:number)=>`${(n/1000).toLocaleString('zh-CN',{maximumFractionDigits:3})}`;onMounted(()=>store.load())
</script>
<template><section class="inventory-page"><header class="inventory-header"><div><h1>{{batchOnly?'批次出入明细':'出入库明细'}}</h1><p>流水只追加不修改；来源模块未接入时保留来源编号，不伪造单据详情。</p></div><InventoryScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><InventorySubnav/><div class="inventory-panel inventory-filter"><label>方向<select v-model="direction"><option value="">全部</option><option value="inbound">入库</option><option value="outbound">出库</option></select></label><label class="keyword">来源 / 商品 / 批次<input v-model="keyword" placeholder="来源编号 / SKU / 批次"></label></div><div v-if="error" class="inventory-state error">{{error}}<button class="inv-button" @click="store.load">重试</button></div><div v-else-if="loading" class="inventory-state">正在加载流水…</div><div v-else-if="!rows.length" class="inventory-state">暂无库存流水</div><div v-else class="inventory-table-wrap" style="margin-top:12px"><table class="inventory-table"><thead><tr><th>来源</th><th>方向</th><th>仓库 / 库位</th><th>商品 / SKU</th><th>批次</th><th v-if="batchOnly">生产 / 有效期</th><th class="quantity">变动数量</th><th class="quantity">变动后</th><th class="money">成本单价</th><th>操作时间 / 人</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.sourceType}}<small>{{row.sourceId}} · 对应模块未接入</small></td><td>{{row.direction==='inbound'?'入库':'出库'}}</td><td>{{row.warehouseName}}<small>{{row.locationName}}</small></td><td>{{row.sku?.productName??'商品资料不可用'}}<small>{{row.sku?.skuCode??row.skuId}}</small></td><td>{{row.batchNumber}}</td><td v-if="batchOnly">{{row.productionDate??'—'}}<small>{{row.expiresOn??'无有效期'}}</small></td><td class="quantity">{{row.direction==='inbound'?'+':'-'}}{{q(row.quantityMilli)}}</td><td class="quantity">{{q(row.balanceAfterMilli)}}</td><td class="money">{{actor.role==='sales-supervisor'?'—':`¥${(row.costPerBaseUnitCents/100).toFixed(2)}`}}</td><td>{{row.occurredAt.slice(0,16).replace('T',' ')}}<small>{{row.operatorId}}</small></td></tr></tbody></table></div></section></template>
